using Clary.Api.Identity;
using Npgsql;
using NpgsqlTypes;
namespace Clary.Api;
public sealed partial class TicketRepository {
 public async Task<TicketDto> PrepareAsync(CompanyContext c,Guid id,CancellationToken ct){
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);
  await Lock(conn,tx,c,id,ct);var ticket=await Get(conn,tx,c,id,ct)??throw new InventoryMissing();
  if(!TicketAccess.Manager(c)&&!TicketAccess.Assigned(ticket,c))throw new CompanyDenied();
  if(ticket.Type is "Equipment" or "Onboarding" && ticket.Status is not ("Complete" or "Canceled") && ticket.Lines.Count>0 && !ticket.Assets.Any(a=>a.Outcome=="Assign")){
   await Fulfillment(conn,tx,c,ticket,null,ct);
   await using var q=Q(conn,tx,c,"UPDATE equipment_tickets SET revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@id");q.Parameters.AddWithValue("id",id);await q.ExecuteNonQueryAsync(ct);
   await Activity(conn,tx,c,id,"Equipment reserved","Available equipment selected for collection",ct);
   await AuditRepository.AppendAsync(conn,tx,c,"Equipment reserved","equipment-ticket",id,ticket,await Get(conn,tx,c,id,ct),ct);
  }
  var result=(await Get(conn,tx,c,id,ct))!;await tx.CommitAsync(ct);return result;
 }
 record AssetState(Guid Id,int Revision,string Status,Guid? Employee,string? Assignee,Guid? Location,string Category,Guid? Type,string? Custom);
 async Task<AssetState> Asset(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,Guid id,CancellationToken ct){await using var q=Q(conn,tx,c,"SELECT id,revision,status,employee_id,assignee,location_id,category,asset_type_id,custom_category FROM inventory_assets WHERE company_id=@company AND id=@id FOR UPDATE");q.Parameters.AddWithValue("id",id);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new ArgumentException("Choose an asset from this company.");return new(r.GetGuid(0),r.GetInt32(1),r.GetString(2),r.IsDBNull(3)?null:r.GetGuid(3),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetGuid(5),r.GetString(6),r.IsDBNull(7)?null:r.GetGuid(7),r.IsDBNull(8)?null:r.GetString(8));}
 internal async Task SaveAssetLinks(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,Guid ticket,IReadOnlyList<TicketAssetInput> desired,CancellationToken ct){
  var t=(await Get(conn,tx,c,ticket,ct))!;
  if(desired.Any(x=>x.Outcome is not ("Reference" or "Assign" or "Repair" or "Retire")))throw new ArgumentException("Choose a valid inventory outcome.");
  foreach(var x in desired)if(x.Outcome!="Reference"&&(x.Outcome=="Assign"?(t.Type is not ("Equipment" or "Onboarding")||t.RecipientEmployeeId is null):x.Outcome=="Repair"?t.Type!="Repair":t.Type!="Retirement"))throw new ArgumentException("The inventory outcome must match the ticket type and recipient.");
  var old=new List<(Guid Id,string Outcome,int? Owned)>();await using(var q=Q(conn,tx,c,"SELECT asset_id,outcome,owned_revision FROM ticket_asset_links WHERE company_id=@company AND ticket_id=@ticket ORDER BY asset_id")){q.Parameters.AddWithValue("ticket",ticket);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))old.Add((r.GetGuid(0),r.GetString(1),r.IsDBNull(2)?null:r.GetInt32(2)));}
  foreach(var x in old){if(desired.Any(a=>a.AssetId==x.Id&&a.Outcome==x.Outcome))continue;if(x.Owned is not null)throw new InventoryConflict("This asset already has ticket activity. Cancel or finish its existing inventory action before removing it.");await using var q=Q(conn,tx,c,"DELETE FROM ticket_asset_reservations WHERE company_id=@company AND ticket_id=@ticket AND asset_id=@asset; DELETE FROM ticket_asset_links WHERE company_id=@company AND ticket_id=@ticket AND asset_id=@asset");q.Parameters.AddWithValue("ticket",ticket);q.Parameters.AddWithValue("asset",x.Id);await q.ExecuteNonQueryAsync(ct);}
  foreach(var x in desired.OrderBy(x=>x.AssetId)){if(old.Any(o=>o.Id==x.AssetId&&o.Outcome==x.Outcome))continue;var a=await Asset(conn,tx,c,x.AssetId,ct);if(x.Outcome=="Assign"&&(a.Status!="Available"||a.Employee is not null||!string.IsNullOrWhiteSpace(a.Assignee)))throw new InventoryConflict("Choose Available, unassigned inventory.");
   await using(var q=Q(conn,tx,c,"INSERT INTO ticket_asset_links(company_id,ticket_id,asset_id,outcome,baseline_revision,baseline_status,baseline_employee_id,baseline_assignee,baseline_location_id) VALUES(@company,@ticket,@asset,@outcome,@revision,@status,@employee,@assignee,@location)")){q.Parameters.AddWithValue("ticket",ticket);q.Parameters.AddWithValue("asset",a.Id);q.Parameters.AddWithValue("outcome",x.Outcome);q.Parameters.AddWithValue("revision",a.Revision);q.Parameters.AddWithValue("status",a.Status);P(q,"employee",a.Employee,NpgsqlDbType.Uuid);P(q,"assignee",a.Assignee,NpgsqlDbType.Text);P(q,"location",a.Location,NpgsqlDbType.Uuid);await q.ExecuteNonQueryAsync(ct);}
   if(x.Outcome!="Reference"){await using var q=Q(conn,tx,c,"INSERT INTO ticket_asset_reservations(company_id,asset_id,ticket_id) VALUES(@company,@asset,@ticket) ON CONFLICT(company_id,asset_id) DO NOTHING");q.Parameters.AddWithValue("asset",a.Id);q.Parameters.AddWithValue("ticket",ticket);if(await q.ExecuteNonQueryAsync(ct)!=1)throw new InventoryConflict("This asset is reserved by another ticket.");}
  }
 }
 async Task Fulfillment(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,TicketDto ticket,IReadOnlyList<Guid>? selected,CancellationToken ct){
  if(ticket.Type is not ("Equipment" or "Onboarding"))return;
  await Exists(conn,tx,c,"employees",ticket.RecipientEmployeeId,ct);if(ticket.RecipientEmployeeId is null)throw new InventoryConflict("Choose the intended recipient.");
  var links=ticket.Assets.Where(a=>a.Outcome=="Assign").ToList();
  if(links.Count==0&&ticket.Lines.Count>0){var ids=new List<Guid>();await using(var q=Q(conn,tx,c,"SELECT a.id FROM inventory_assets a WHERE a.company_id=@company AND a.status='Available' AND a.employee_id IS NULL AND nullif(btrim(a.assignee),'') IS NULL AND NOT EXISTS(SELECT 1 FROM ticket_asset_reservations r WHERE r.company_id=a.company_id AND r.asset_id=a.id) ORDER BY a.id FOR UPDATE OF a")){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))ids.Add(r.GetGuid(0));}
   if(selected is not null){if(selected.Distinct().Count()!=selected.Count||selected.Count!=ticket.Lines.Sum(l=>l.Quantity))throw new InventoryConflict("Choose exactly the required number of distinct assets.");ids=ids.Where(selected.Contains).ToList();}
   var stock=new List<AssetState>();foreach(var id in ids)stock.Add(await Asset(conn,tx,c,id,ct));var chosen=new List<Guid>();foreach(var line in ticket.Lines.OrderBy(l=>l.CustomCategory is null?1:0)){var matches=stock.Where(a=>!chosen.Contains(a.Id)&&(line.AssetTypeId.HasValue?a.Type==line.AssetTypeId:a.Category==line.Category)&&(line.CustomCategory is null||string.Equals(a.Custom,line.CustomCategory,StringComparison.OrdinalIgnoreCase))).Take(line.Quantity).ToList();if(matches.Count!=line.Quantity)throw new InventoryConflict("Insufficient Available inventory for the complete kit.");chosen.AddRange(matches.Select(a=>a.Id));}
   await SaveAssetLinks(conn,tx,c,ticket.Id,ticket.Assets.Select(a=>new TicketAssetInput(a.Id,a.Outcome)).Concat(chosen.Select(a=>new TicketAssetInput(a,"Assign"))).ToArray(),ct);
   links=(await Get(conn,tx,c,ticket.Id,ct))!.Assets.Where(a=>a.Outcome=="Assign").ToList();
  }
  if(links.Count==0)throw new InventoryConflict("Link the equipment to assign before completing this ticket.");
  if(ticket.Lines.Count>0){var remaining=new List<AssetState>();foreach(var a in links)remaining.Add(await Asset(conn,tx,c,a.Id,ct));foreach(var line in ticket.Lines.OrderBy(l=>l.CustomCategory is null?1:0)){var matches=remaining.Where(a=>(line.AssetTypeId.HasValue?a.Type==line.AssetTypeId:a.Category==line.Category)&&(line.CustomCategory is null||string.Equals(a.Custom,line.CustomCategory,StringComparison.OrdinalIgnoreCase))).Take(line.Quantity).ToList();if(matches.Count!=line.Quantity)throw new InventoryConflict("Linked assets do not match the required equipment.");foreach(var a in matches)remaining.Remove(a);}if(remaining.Count>0)throw new InventoryConflict("The linked assets exceed the required equipment.");}
 }
 async Task ApplyInventory(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,TicketDto ticket,string action,CancellationToken ct){
  if(action=="complete")await Fulfillment(conn,tx,c,ticket,null,ct);
  var links=new List<(Guid Id,string Outcome,int Baseline,int? Owned)>();await using(var q=Q(conn,tx,c,"SELECT asset_id,outcome,baseline_revision,owned_revision FROM ticket_asset_links WHERE company_id=@company AND ticket_id=@ticket ORDER BY asset_id")){q.Parameters.AddWithValue("ticket",ticket.Id);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))links.Add((r.GetGuid(0),r.GetString(1),r.GetInt32(2),r.IsDBNull(3)?null:r.GetInt32(3)));}
  foreach(var link in links){if(link.Outcome=="Reference")continue;var asset=await Asset(conn,tx,c,link.Id,ct);string? status=null;Guid? employee=asset.Employee;
   if(action=="cancel"){if(link.Outcome=="Assign"&&link.Owned is not null){if(asset.Revision!=link.Owned||asset.Employee!=ticket.RecipientEmployeeId)throw new InventoryConflict("An asset changed after this ticket assigned it. Resolve that ownership before canceling.");status="Available";employee=null;}}
   else if(action=="complete"){if(asset.Revision!=(link.Owned??link.Baseline))throw new InventoryConflict("Linked inventory changed. Refresh and resolve it before completing.");
    if(link.Outcome=="Assign"){if(asset.Status=="Assigned"&&asset.Employee==ticket.RecipientEmployeeId&&(link.Owned is not null||ticket.RequestId is not null))continue;if(asset.Status!="Available"||asset.Employee is not null||!string.IsNullOrWhiteSpace(asset.Assignee))throw new InventoryConflict("Linked equipment is no longer available.");status="Assigned";employee=ticket.RecipientEmployeeId;}
    else if(link.Outcome=="Repair"){status=ticket.RecipientEmployeeId is null?"Available":"Assigned";employee=ticket.RecipientEmployeeId;}
    else {status="Retired";employee=null;}
   }else if(action=="send-for-repair"||action=="start"&&ticket.Type=="Repair"){if(link.Outcome=="Repair"&&asset.Status!="In repair"){if(asset.Revision!=(link.Owned??link.Baseline))throw new InventoryConflict("The repair asset changed. Refresh the ticket.");status="In repair";}}
   if(status is null)continue;
   if(employee is not null)await Exists(conn,tx,c,"employees",employee,ct);await Exists(conn,tx,c,"locations",ticket.LocationId,ct);await Exists(conn,tx,c,"inventory_departments",ticket.DepartmentId,ct);
   var before=await AuditRepository.SnapshotAsync(conn,tx,c,"inventory_assets","id",asset.Id,ct);
   await using(var q=Q(conn,tx,c,"UPDATE inventory_assets SET status=@status,employee_id=@employee,assignee=CASE WHEN @employee IS NULL THEN NULL ELSE (SELECT display_name FROM employees WHERE company_id=@company AND id=@employee) END,department_id=CASE WHEN @department IS NULL THEN department_id ELSE @department END,department=CASE WHEN @department IS NULL THEN department ELSE (SELECT name FROM inventory_departments WHERE company_id=@company AND id=@department) END,location_id=coalesce(@location,location_id),location=CASE WHEN @location IS NULL THEN location ELSE (SELECT name FROM locations WHERE company_id=@company AND id=@location) END,revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@asset; UPDATE ticket_asset_links SET owned_revision=@revision,completed=@complete WHERE company_id=@company AND ticket_id=@ticket AND asset_id=@asset")){q.Parameters.AddWithValue("status",status);P(q,"employee",employee,NpgsqlDbType.Uuid);P(q,"department",ticket.DepartmentId,NpgsqlDbType.Uuid);P(q,"location",ticket.LocationId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("asset",asset.Id);q.Parameters.AddWithValue("ticket",ticket.Id);q.Parameters.AddWithValue("revision",asset.Revision+1);q.Parameters.AddWithValue("complete",action=="complete");await q.ExecuteNonQueryAsync(ct);}
   await AuditRepository.AppendAsync(conn,tx,c,status,"asset",asset.Id,before,await AuditRepository.SnapshotAsync(conn,tx,c,"inventory_assets","id",asset.Id,ct),ct,ticket.Id);
   await using(var q=Q(conn,tx,c,"INSERT INTO inventory_activity(company_id,id,asset_id,computer,kind) SELECT @company,@id,id,computer,@kind FROM inventory_assets WHERE company_id=@company AND id=@asset; DELETE FROM directory_mapping_review WHERE company_id=@company AND asset_id=@asset AND kind IN ('employee','department')")){q.Parameters.AddWithValue("id",Guid.NewGuid());q.Parameters.AddWithValue("kind",status);q.Parameters.AddWithValue("asset",asset.Id);await q.ExecuteNonQueryAsync(ct);}
  }
  if(action is "complete" or "cancel"){await using var q=Q(conn,tx,c,"DELETE FROM ticket_asset_reservations WHERE company_id=@company AND ticket_id=@ticket");q.Parameters.AddWithValue("ticket",ticket.Id);await q.ExecuteNonQueryAsync(ct);}
 }
}
